//! Offline contracts: source sets are manually reviewed, not generated by another analyzer.
use serde::Deserialize;
use std::{collections::BTreeMap, time::SystemTime};
use yasp::{
    catalog::*,
    lineage::*,
    query::{InputOptions, ParsedQuery, SqlDialect},
};

#[derive(Deserialize)]
struct Case {
    name: String,
    #[serde(default)]
    dialects: Vec<SqlDialect>,
    sql: String,
    sources: Vec<Vec<String>>,
}

fn schema(dialect: SqlDialect) -> Snapshot {
    let spelling = |name: &str| {
        if dialect == SqlDialect::Snowflake {
            name.to_ascii_uppercase()
        } else {
            name.into()
        }
    };
    let mut relations = BTreeMap::new();
    for (name, columns) in [
        (
            "users",
            vec![
                ("id", "int"),
                ("email", "text"),
                ("profile", "jsonb"),
                ("created_at", "timestamp"),
                ("context_key", "text"),
            ],
        ),
        (
            "support_tickets",
            vec![
                ("id", "int"),
                ("email", "text"),
                ("user_id", "int"),
                ("subject", "text"),
            ],
        ),
        ("listing", vec![("listid", "int")]),
        (
            "sales",
            vec![
                ("listid", "int"),
                ("pricepaid", "numeric"),
                ("commission", "numeric"),
                ("dateid", "int"),
            ],
        ),
        (
            "stg_customers",
            vec![
                ("customer_id", "int"),
                ("first_name", "text"),
                ("last_name", "text"),
            ],
        ),
        (
            "stg_orders",
            vec![
                ("order_id", "int"),
                ("customer_id", "int"),
                ("order_date", "date"),
                ("status", "text"),
            ],
        ),
        (
            "stg_payments",
            vec![
                ("payment_id", "int"),
                ("order_id", "int"),
                ("amount", "numeric"),
            ],
        ),
        ("car_sales", vec![("src", "variant")]),
    ] {
        let id = RelationId {
            database: "analytics".into(),
            schema: spelling("public"),
            name: spelling(name),
        };
        let columns = columns
            .into_iter()
            .enumerate()
            .map(|(i, (name, ty))| Column {
                id: ColumnId {
                    relation: id.clone(),
                    name: spelling(name),
                },
                ordinal: i as u32 + 1,
                native_type: NativeType {
                    name: if name == "profile" && dialect == SqlDialect::Redshift {
                        "super"
                    } else {
                        ty
                    }
                    .into(),
                    character_length: None,
                    precision: None,
                    scale: None,
                    datetime_precision: None,
                    postgres_oid: None,
                    postgres_modifier: None,
                },
                nullable: true,
                default: None,
                comment: None,
                identity: false,
                generated: None,
                primary_key: None,
            })
            .collect();
        relations.insert(
            id.clone(),
            Relation {
                id,
                kind: RelationKind::Table,
                comment: None,
                native_id: None,
                selectable: None,
                view_definition: None,
                constraints: None,
                columns,
            },
        );
    }
    Snapshot {
        postgres: None,
        generation: 1,
        loaded_at: SystemTime::now(),
        source: SourceIdentity {
            dialect,
            endpoint: "fixture".into(),
            principal: "discovery".into(),
            role: None,
            warehouse: None,
            default_schema: None,
        },
        schemas: [("analytics".into(), spelling("public"))].into(),
        relations,
    }
}

fn parse(sql: &str, dialect: SqlDialect) -> ParsedQuery {
    ParsedQuery::parse_with_options(sql, 1_048_576, InputOptions::native(dialect))
        .unwrap_or_else(|e| panic!("{dialect:?}: {sql}: {e}"))
}

fn source_name(source: &LineageSource) -> String {
    match source {
        LineageSource::Unknown { reference } => format!("?{}", reference.to_ascii_lowercase()),
        LineageSource::Column { column, path } => {
            let mut result =
                format!("{}.{}", column.relation.name, column.name).to_ascii_lowercase();
            for part in path {
                result.push_str(&match part {
                    PathSegment::Key(s) => format!(":{s}"),
                    PathSegment::Index(i) => format!("[{i}]"),
                    PathSegment::Element { element } => format!(":{{{element}}}"),
                    PathSegment::Unknown { .. } => ":?".into(),
                    PathSegment::Any { .. } => "[*]".into(),
                });
            }
            result
        }
    }
}

#[test]
fn schema_backed_analytics_corpus() {
    let cases: Vec<Case> = serde_json::from_str(include_str!("fixtures/lineage.json")).unwrap();
    let mut count = 0;
    for dialect in [
        SqlDialect::Postgresql,
        SqlDialect::Snowflake,
        SqlDialect::Redshift,
    ] {
        let schema = schema(dialect);
        for case in &cases {
            if !case.dialects.is_empty() && !case.dialects.contains(&dialect) {
                continue;
            }
            let context =
                AstDataContext::analyze(&parse(&case.sql, dialect), Some(&schema), 65_536);
            assert!(
                !context.unknown_outputs,
                "{} {dialect:?}: {:?}",
                case.name, context
            );
            let actual: Vec<Vec<_>> = context
                .columns
                .iter()
                .map(|c| c.sources.iter().map(source_name).collect())
                .collect();
            assert_eq!(actual, case.sources, "{} {dialect:?}", case.name);
            count += 1;
        }
    }
    assert!(count > 90, "the corpus exercises all three dialects");
}

#[test]
fn uncertainty_and_actual_output_shape_are_explicit() {
    let schema = schema(SqlDialect::Postgresql);
    let query = parse(
        "SELECT u.id, x.* FROM users u, missing x",
        SqlDialect::Postgresql,
    );
    let context = AstDataContext::analyze(&query, Some(&schema), 65_536);
    assert!(context.unknown_outputs);
    assert_eq!(source_name(&context.columns[0].sources[0]), "users.id");
    let unknown_first = AstDataContext::analyze(
        &parse(
            "SELECT x.*,u.id FROM users u, missing x",
            SqlDialect::Postgresql,
        ),
        Some(&schema),
        65_536,
    );
    assert!(unknown_first.unknown_outputs);
    assert!(
        unknown_first.columns.is_empty(),
        "the position of id is unknown"
    );
    let known_prefix = AstDataContext::analyze(
        &parse(
            "SELECT u.id,x.*,u.email FROM users u, missing x",
            SqlDialect::Postgresql,
        ),
        Some(&schema),
        65_536,
    );
    assert!(known_prefix.unknown_outputs);
    assert_eq!(
        known_prefix.columns.len(),
        1,
        "only the prefix has known positions"
    );
    let aligned = context.for_columns(&["id", "anything", "else"]);
    assert_eq!(aligned.columns.len(), 3);
    assert_eq!(source_name(&aligned.columns[0].sources[0]), "users.id");
    assert!(
        aligned
            .columns
            .iter()
            .skip(1)
            .all(|c| matches!(c.sources.as_slice(), [LineageSource::Unknown { .. }]))
    );
    let mismatched = context.for_columns(&["different", "anything"]);
    assert!(
        mismatched
            .columns
            .iter()
            .all(|c| matches!(c.sources.as_slice(), [LineageSource::Unknown { .. }]))
    );
    let absent = AstDataContext::analyze(
        &parse("SELECT CONCAT(id,email)", SqlDialect::Postgresql),
        None,
        65_536,
    );
    assert_eq!(absent.columns[0].sources.len(), 2);
    let constant =
        AstDataContext::analyze(&parse("SELECT 1", SqlDialect::Postgresql), None, 65_536);
    assert!(constant.columns[0].sources.is_empty());
    let bounded = AstDataContext::analyze(&query, Some(&schema), 8);
    assert!(bounded.unknown_outputs && bounded.columns.is_empty());
}

#[test]
fn expanded_intermediate_values_obey_the_context_budget() {
    let schema = schema(SqlDialect::Postgresql);
    let query = parse(
        &format!(
            "SELECT CONCAT(profile->'{}',email,id) FROM users",
            "x".repeat(8192)
        ),
        SqlDialect::Postgresql,
    );
    let context = AstDataContext::analyze(&query, Some(&schema), 4096);
    let sources = &context.columns[0].sources;
    assert!(sources.iter().any(|s| source_name(s) == "users.email"));
    assert!(
        sources
            .iter()
            .any(|s| matches!(s, LineageSource::Unknown { .. }))
    );

    let projection = (0..200)
        .map(|i| format!("p->'key{i}' AS c{i}"))
        .collect::<Vec<_>>()
        .join(",");
    let query = parse(
        &format!("WITH c AS (SELECT profile AS p FROM users) SELECT {projection} FROM c"),
        SqlDialect::Postgresql,
    );
    let context = AstDataContext::analyze(&query, Some(&schema), 4096);
    assert!(context.unknown_outputs);
    assert!(serde_json::to_vec(&context).unwrap().len() <= 4096);

    let query = parse(
        &format!("SELECT {} FROM users", vec!["id"; 256].join("+")),
        SqlDialect::Postgresql,
    );
    let context = AstDataContext::analyze(&query, Some(&schema), 65_536);
    assert!(
        context.columns[0]
            .sources
            .iter()
            .any(|s| matches!(s, LineageSource::Unknown { .. }))
    );
}

#[test]
fn quoted_coordinates_and_key_case_survive_serialization() {
    let mut schema = schema(SqlDialect::Postgresql);
    let mut relation = schema
        .relations
        .values()
        .find(|r| r.id.name == "users")
        .unwrap()
        .clone();
    relation.id.name = "a.b".into();
    relation.columns.truncate(1);
    relation.columns[0].id = ColumnId {
        relation: relation.id.clone(),
        name: "Mixed\"Case".into(),
    };
    schema.relations.insert(relation.id.clone(), relation);
    let context = AstDataContext::analyze(
        &parse(
            "SELECT \"Mixed\"\"Case\"->'Email' FROM \"a.b\"",
            SqlDialect::Postgresql,
        ),
        Some(&schema),
        65_536,
    );
    let value = serde_json::to_value(context).unwrap();
    assert_eq!(
        value["columns"][0]["sources"][0]["column"],
        "\"analytics\".\"public\".\"a.b\".\"Mixed\"\"Case\""
    );
    assert_eq!(value["columns"][0]["sources"][0]["path"][0], "Email");
}

#[test]
fn recursive_scopes_and_unsupported_nodes_do_not_claim_empty_lineage() {
    let schema = schema(SqlDialect::Postgresql);
    let query = parse(
        "WITH RECURSIVE c AS(SELECT id FROM users UNION ALL SELECT id+1 FROM c) SELECT id FROM c",
        SqlDialect::Postgresql,
    );
    let result = AstDataContext::analyze(&query, Some(&schema), 65_536);
    assert!(matches!(
        &result.columns[0].sources[0],
        LineageSource::Unknown { .. }
    ));
    let query = parse(
        "SELECT id FROM users INTERSECT SELECT user_id FROM support_tickets",
        SqlDialect::Postgresql,
    );
    let result = AstDataContext::analyze(&query, Some(&schema), 65_536);
    assert!(
        result.columns[0]
            .sources
            .iter()
            .any(|s| matches!(s, LineageSource::Unknown { .. }))
    );
}

#[test]
fn ast_context_configuration_is_optional_and_has_no_dictionary_options() {
    let settings: yasp::config::DataContextsSettings = serde_json::from_str("{}").unwrap();
    assert!(!settings.ast.enabled);
    assert_eq!(settings.ast.dialect, None);
    let settings: yasp::config::DataContextsSettings =
        serde_json::from_str(r#"{"ast":{"enabled":true}}"#).unwrap();
    assert!(settings.ast.enabled);
    for dialect in [
        SqlDialect::Postgresql,
        SqlDialect::Snowflake,
        SqlDialect::Redshift,
    ] {
        let settings: yasp::config::DataContextsSettings =
            serde_json::from_value(serde_json::json!({"ast":{"dialect":dialect}})).unwrap();
        assert_eq!(settings.ast.dialect, Some(dialect));
        assert!(!settings.ast.enabled);
        assert_eq!(
            serde_json::to_value(settings).unwrap()["ast"]["dialect"],
            serde_json::to_value(dialect).unwrap()
        );
    }
    assert!(
        serde_json::from_str::<yasp::config::DataContextsSettings>(
            r#"{"ast":{"dialect":"unsupported"}}"#
        )
        .is_err()
    );
    assert!(
        serde_json::from_str::<yasp::config::DataContextsSettings>(
            r#"{"ast":{"enabled":true,"dictionary":"emails"}}"#
        )
        .is_err()
    );
    assert!(
        serde_json::from_str::<yasp::config::DataContextsSettings>(r#"{"ast":{"enabled":"yes"}}"#)
            .is_err()
    );
}
